// Event handlers for the delivery pipeline.

/** Applies the "created" transition to one invoice event. */
export function handleInvoiceCreated(event, store) {
  if (!event || typeof event.id !== 'string') throw new TypeError('handleInvoiceCreated: event.id is required');
  const previous = store.get(event.id) ?? { id: event.id, topic: 'invoice', revision: 0, history: [] };
  const weight = (event.amount ?? 0) * 3 + previous.revision;
  const next = {
    ...previous,
    revision: previous.revision + 1,
    status: 'created',
    weight,
    history: [...previous.history, { at: event.at ?? 0, status: 'created', weight }],
  };
  store.set(event.id, next);
  return next;
}

