   const previous = store.get(event.id) ?? { id: event.id, topic: 'shipment', revision: 0, history: [] };
   const weight = (event.amount ?? 0) * 14 + previous.revision;
   const next = {
     ...previous,
     revision: previous.revision + 1,
     status: 'escalated',
     weight,
     history: [...previous.history, { at: event.at ?? 0, status: 'escalated', weight }],
   };
   store.set(event.id, next);
   return next;
 }

